"""Lexer and recursive-descent parser for minisql. See SPEC.md, "Syntax".

``parse(sql)`` turns a query string into a ``nodes.Select`` tree, raising
``QueryError`` for any syntax error.

Notes on choices not pinned down by the spec:

* Comparisons don't chain: ``a = b = c`` (or ``a IS NULL = TRUE``) is a
  syntax error. Parenthesize to compare the result of a comparison.
* ``NOT`` sits below comparisons, so ``a = NOT b`` is a syntax error
  (write ``a = (NOT b)``); ``NOT NOT x`` is fine.
* ``name(*)`` is accepted for any function name (``star=True``); the
  executor rejects it for anything but ``COUNT``.
* SQL comments are not supported (``--`` is two minus signs).
* A number immediately followed by a letter, digit, underscore or ``.``
  (``1e5``, ``1.2.3``, ``12abc``) is a syntax error rather than being
  split into separate tokens.
"""

from . import nodes
from .errors import QueryError

KEYWORDS = frozenset(
    """
    SELECT DISTINCT FROM WHERE GROUP BY HAVING ORDER ASC DESC LIMIT OFFSET
    AS AND OR NOT IS NULL IN BETWEEN LIKE TRUE FALSE
    """.split()
)

COMPARISON_OPS = ("=", "!=", "<>", "<", "<=", ">", ">=")

# Longest first, so that "<=" wins over "<".
OPERATORS = ("<=", ">=", "<>", "!=", "||", "=", "<", ">", "+", "-", "*", "/",
             "(", ")", ",", ";")

# Token kinds
KW = "keyword"
NAME = "name"      # unquoted identifier
QNAME = "qname"    # double-quoted identifier
INT = "integer"
FLOAT = "decimal"
STR = "string"
OP = "operator"
EOF = "end of input"


class Token:
    __slots__ = ("kind", "value", "start", "end")

    def __init__(self, kind, value, start, end):
        self.kind = kind
        self.value = value
        self.start = start
        self.end = end

    def __repr__(self):
        return "Token(%s, %r, %d, %d)" % (self.kind, self.value, self.start, self.end)


def _is_ident_start(c):
    return c == "_" or ("a" <= c <= "z") or ("A" <= c <= "Z")


def _is_ident_char(c):
    return _is_ident_start(c) or ("0" <= c <= "9")


def _is_digit(c):
    return "0" <= c <= "9"


def tokenize(sql):
    tokens = []
    i = 0
    n = len(sql)
    while i < n:
        c = sql[i]
        if c.isspace():
            i += 1
            continue
        start = i
        if _is_ident_start(c):
            while i < n and _is_ident_char(sql[i]):
                i += 1
            word = sql[start:i]
            upper = word.upper()
            if upper in KEYWORDS:
                tokens.append(Token(KW, upper, start, i))
            else:
                tokens.append(Token(NAME, word, start, i))
        elif _is_digit(c) or (c == "." and i + 1 < n and _is_digit(sql[i + 1])):
            while i < n and _is_digit(sql[i]):
                i += 1
            is_float = False
            if i < n and sql[i] == ".":
                is_float = True
                i += 1
                while i < n and _is_digit(sql[i]):
                    i += 1
            if i < n and (_is_ident_char(sql[i]) or sql[i] == "."):
                raise QueryError(
                    "syntax error: malformed number %r at position %d"
                    % (sql[start:i + 1], start)
                )
            text = sql[start:i]
            if is_float:
                tokens.append(Token(FLOAT, float(text), start, i))
            else:
                tokens.append(Token(INT, int(text), start, i))
        elif c == "'" or c == '"':
            quote = c
            i += 1
            parts = []
            while True:
                j = sql.find(quote, i)
                if j < 0:
                    what = "string" if quote == "'" else "quoted name"
                    raise QueryError(
                        "syntax error: unterminated %s starting at position %d"
                        % (what, start)
                    )
                parts.append(sql[i:j])
                if j + 1 < n and sql[j + 1] == quote:
                    parts.append(quote)
                    i = j + 2
                else:
                    i = j + 1
                    break
            value = "".join(parts)
            if quote == "'":
                tokens.append(Token(STR, value, start, i))
            else:
                if value == "":
                    raise QueryError(
                        "syntax error: empty quoted name at position %d" % start
                    )
                tokens.append(Token(QNAME, value, start, i))
        else:
            for op in OPERATORS:
                if sql.startswith(op, i):
                    i += len(op)
                    tokens.append(Token(OP, op, start, i))
                    break
            else:
                raise QueryError(
                    "syntax error: unexpected character %r at position %d" % (c, start)
                )
    tokens.append(Token(EOF, None, n, n))
    return tokens


class Parser:
    def __init__(self, sql):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0
        self.prev_end = 0

    # ----- token helpers -------------------------------------------------

    @property
    def tok(self):
        return self.tokens[self.pos]

    def peek(self, offset=1):
        return self.tokens[min(self.pos + offset, len(self.tokens) - 1)]

    def advance(self):
        t = self.tokens[self.pos]
        if t.kind != EOF:
            self.pos += 1
        self.prev_end = t.end
        return t

    def is_kw(self, *words, tok=None):
        t = self.tok if tok is None else tok
        return t.kind == KW and t.value in words

    def is_op(self, *ops, tok=None):
        t = self.tok if tok is None else tok
        return t.kind == OP and t.value in ops

    def accept_kw(self, word):
        if self.is_kw(word):
            return self.advance()
        return None

    def accept_op(self, op):
        if self.is_op(op):
            return self.advance()
        return None

    def describe(self, t):
        if t.kind == EOF:
            return "end of input"
        return "%r at position %d" % (self.sql[t.start:t.end], t.start)

    def error(self, expected, t=None):
        t = self.tok if t is None else t
        return QueryError("syntax error: expected %s, found %s" % (expected, self.describe(t)))

    def expect_kw(self, word):
        if not self.is_kw(word):
            raise self.error(word)
        return self.advance()

    def expect_op(self, op):
        if not self.is_op(op):
            raise self.error("'%s'" % op)
        return self.advance()

    def expect_name(self, what="a name"):
        t = self.tok
        if t.kind in (NAME, QNAME):
            self.advance()
            return t.value
        if t.kind == KW:
            raise QueryError(
                "syntax error: expected %s, found keyword %s at position %d "
                "(keywords must be double-quoted to be used as names)"
                % (what, t.value, t.start)
            )
        raise self.error(what)

    def text_from(self, start):
        return self.sql[start:self.prev_end]

    # ----- query ---------------------------------------------------------

    def parse_query(self):
        if self.tok.kind == EOF:
            raise QueryError("syntax error: empty query")
        self.expect_kw("SELECT")
        distinct = bool(self.accept_kw("DISTINCT"))

        if self.is_op("*"):
            self.advance()
            columns = None
        else:
            columns = [self.parse_select_item()]
            while self.accept_op(","):
                columns.append(self.parse_select_item())
        if self.is_op(","):
            raise self.error("FROM")  # e.g. "SELECT *, a"

        self.expect_kw("FROM")
        table = self.expect_name("a table name")

        where = None
        if self.accept_kw("WHERE"):
            where = self.parse_expr()

        group_by = []
        if self.accept_kw("GROUP"):
            self.expect_kw("BY")
            group_by.append(self.parse_expr())
            while self.accept_op(","):
                group_by.append(self.parse_expr())

        having = None
        if self.accept_kw("HAVING"):
            having = self.parse_expr()

        order_by = []
        if self.accept_kw("ORDER"):
            self.expect_kw("BY")
            order_by.append(self.parse_order_item())
            while self.accept_op(","):
                order_by.append(self.parse_order_item())

        limit = offset = None
        if self.accept_kw("LIMIT"):
            limit = self.parse_count("LIMIT")
            if self.accept_kw("OFFSET"):
                offset = self.parse_count("OFFSET")

        self.accept_op(";")
        if self.tok.kind != EOF:
            raise self.error("end of query")

        return nodes.Select(
            distinct=distinct,
            columns=columns,
            table=table,
            where=where,
            group_by=group_by,
            having=having,
            order_by=order_by,
            limit=limit,
            offset=offset,
        )

    def parse_select_item(self):
        if self.is_op("*"):
            raise QueryError(
                "syntax error: '*' at position %d must be the only item in the "
                "column list" % self.tok.start
            )
        expr = self.parse_expr()
        alias = None
        if self.accept_kw("AS"):
            alias = self.expect_name("a column alias after AS")
        elif self.tok.kind in (NAME, QNAME):
            alias = self.advance().value
        return nodes.SelectItem(expr, alias)

    def parse_order_item(self):
        expr = self.parse_expr()
        desc = False
        if self.accept_kw("DESC"):
            desc = True
        else:
            self.accept_kw("ASC")
        return nodes.OrderItem(expr, desc)

    def parse_count(self, clause):
        t = self.tok
        if t.kind != INT:
            raise self.error("a non-negative integer after %s" % clause)
        self.advance()
        return t.value

    # ----- expressions ---------------------------------------------------

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        start = self.tok.start
        left = self.parse_and()
        while self.accept_kw("OR"):
            right = self.parse_and()
            left = nodes.Binary("OR", left, right, text=self.text_from(start))
        return left

    def parse_and(self):
        start = self.tok.start
        left = self.parse_not()
        while self.accept_kw("AND"):
            right = self.parse_not()
            left = nodes.Binary("AND", left, right, text=self.text_from(start))
        return left

    def parse_not(self):
        start = self.tok.start
        if self.accept_kw("NOT"):
            operand = self.parse_not()
            return nodes.Unary("NOT", operand, text=self.text_from(start))
        return self.parse_comparison()

    def _at_comparison(self):
        t = self.tok
        if t.kind == OP and t.value in COMPARISON_OPS:
            return True
        if self.is_kw("IS", "IN", "BETWEEN", "LIKE"):
            return True
        if self.is_kw("NOT") and self.is_kw("IN", "BETWEEN", "LIKE", tok=self.peek()):
            return True
        return False

    def parse_comparison(self):
        start = self.tok.start
        left = self.parse_additive()
        if not self._at_comparison():
            return left

        t = self.tok
        if t.kind == OP:
            self.advance()
            right = self.parse_additive()
            node = nodes.Binary(t.value, left, right)
        elif self.accept_kw("IS"):
            negated = bool(self.accept_kw("NOT"))
            if not self.accept_kw("NULL"):
                raise self.error("NULL after IS NOT" if negated else "NULL or NOT NULL after IS")
            node = nodes.IsNull(left, negated)
        else:
            negated = bool(self.accept_kw("NOT"))
            if self.accept_kw("IN"):
                self.expect_op("(")
                if self.is_op(")"):
                    raise self.error("at least one expression in IN list")
                items = [self.parse_expr()]
                while self.accept_op(","):
                    items.append(self.parse_expr())
                self.expect_op(")")
                node = nodes.InList(left, items, negated)
            elif self.accept_kw("BETWEEN"):
                low = self.parse_additive()
                self.expect_kw("AND")
                high = self.parse_additive()
                node = nodes.Between(left, low, high, negated)
            else:
                self.expect_kw("LIKE")
                pattern = self.parse_additive()
                node = nodes.Like(left, pattern, negated)
        node.text = self.text_from(start)

        if self._at_comparison():
            raise QueryError(
                "syntax error: comparisons can't be chained (at %s); use "
                "parentheses" % self.describe(self.tok)
            )
        return node

    def parse_additive(self):
        start = self.tok.start
        left = self.parse_multiplicative()
        while self.is_op("+", "-", "||"):
            op = self.advance().value
            right = self.parse_multiplicative()
            left = nodes.Binary(op, left, right, text=self.text_from(start))
        return left

    def parse_multiplicative(self):
        start = self.tok.start
        left = self.parse_unary()
        while self.is_op("*", "/"):
            op = self.advance().value
            right = self.parse_unary()
            left = nodes.Binary(op, left, right, text=self.text_from(start))
        return left

    def parse_unary(self):
        start = self.tok.start
        if self.accept_op("-"):
            operand = self.parse_unary()
            return nodes.Unary("-", operand, text=self.text_from(start))
        return self.parse_primary()

    def parse_primary(self):
        t = self.tok
        start = t.start

        if t.kind in (INT, FLOAT, STR):
            self.advance()
            return nodes.Literal(t.value, text=self.text_from(start))
        if t.kind == KW:
            if t.value in ("NULL", "TRUE", "FALSE"):
                self.advance()
                value = {"NULL": None, "TRUE": True, "FALSE": False}[t.value]
                return nodes.Literal(value, text=self.text_from(start))
            raise QueryError(
                "syntax error: expected an expression, found keyword %s at "
                "position %d" % (t.value, t.start)
            )
        if t.kind == NAME and self.is_op("(", tok=self.peek()):
            self.advance()
            self.advance()  # "("
            name = t.value.upper()
            if self.is_op("*"):
                self.advance()
                self.expect_op(")")
                return nodes.FuncCall(name, [], star=True, text=self.text_from(start))
            args = []
            if not self.is_op(")"):
                args.append(self.parse_expr())
                while self.accept_op(","):
                    args.append(self.parse_expr())
            self.expect_op(")")
            return nodes.FuncCall(name, args, text=self.text_from(start))
        if t.kind in (NAME, QNAME):
            self.advance()
            return nodes.Column(t.value, text=self.text_from(start))
        if self.accept_op("("):
            inner = self.parse_expr()
            self.expect_op(")")
            inner.text = self.text_from(start)
            return inner
        raise self.error("an expression")


def parse(sql):
    """Parse a minisql query string into a ``nodes.Select``."""
    if not isinstance(sql, str):
        raise QueryError("query must be a string")
    return Parser(sql).parse_query()

"""Evaluate a parsed ``nodes.Select`` against a directory of CSV files.

See SPEC.md (sections "Tables" and "Semantics") for the rules implemented
here. Choices made where the spec is silent:

* CSV files are read as UTF-8 (a leading byte-order mark is ignored).
  A file with no header line is an error. Completely blank lines are
  skipped. Rows shorter than the header are padded with NULLs; rows longer
  than the header are an error.
* If the header has two columns whose names differ only in case, a
  reference to that name is an error (ambiguous); unreferenced duplicates
  are fine.
* Column names, functions, argument counts, aggregate placement and the
  grouped-column rule are checked before any row is read, so they are
  reported even when the table (or the filtered result) is empty.
  Value/type errors are only detected when a value is actually computed.
* ``AND``/``OR`` operands must be booleans or NULL; ``NOT`` needs a boolean
  or NULL; a ``WHERE``/``HAVING`` condition that evaluates to a non-boolean,
  non-NULL value is an error. Both operands of AND/OR are always evaluated.
* ``||`` renders booleans as ``true``/``false`` (matching the CLI output)
  and numbers with ``str()``.
* Equality (``=``, ``!=``, ``IN``) follows the same typing rules as
  ordering comparisons: mixing a number with a string, or a boolean with a
  non-boolean, is an error.
* LIKE requires string operands. ``LOWER``/``UPPER``/``LENGTH`` require a
  string, ``ABS``/``ROUND`` a number, and ``ROUND``'s second argument an
  integer (it may be negative).
* ``HAVING`` without ``GROUP BY`` and without any aggregate does not make
  the query grouped (the spec's definition of "grouped" lists only
  GROUP BY and aggregates); it then filters rows like a second WHERE.
* In grouped queries, a non-aggregate expression is valid if every column
  reference outside an aggregate sits inside a subexpression equal to a
  GROUP BY expression (e.g. ``GROUP BY price * 2`` allows
  ``SELECT price * 2 + 1``). Such expressions are evaluated on the group's
  first row.
* Groups and DISTINCT treat 1 and 1.0 as equal (numbers compare
  numerically) but keep TRUE distinct from 1.
* ``LIMIT``/``OFFSET`` must not be negative.
"""

import csv
import decimal
import functools
import os
import re

from . import nodes
from .errors import QueryError

__all__ = ["Result", "execute"]


class Result:
    """The result of a query: ``columns`` (list of str), ``rows`` (list of
    tuples)."""

    def __init__(self, columns, rows):
        self.columns = list(columns)
        self.rows = list(rows)

    def __repr__(self):
        return "Result(columns=%r, rows=%r)" % (self.columns, self.rows)

    def __eq__(self, other):
        if not isinstance(other, Result):
            return NotImplemented
        return self.columns == other.columns and self.rows == other.rows

    def __len__(self):
        return len(self.rows)

    def __iter__(self):
        return iter(self.rows)


# ---------------------------------------------------------------------------
# Tables

_INT_RE = re.compile(r"-?[0-9]+")
_FLOAT_RE = re.compile(r"-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+")


def _convert(field):
    if field == "":
        return None
    if _INT_RE.fullmatch(field):
        return int(field)
    if _FLOAT_RE.fullmatch(field):
        return float(field)
    return field


class _Table:
    def __init__(self, header, rows):
        self.header = header
        self.rows = rows
        self._index = {}
        for i, name in enumerate(header):
            self._index.setdefault(name.lower(), []).append(i)

    def resolve(self, name):
        """Return the index of column ``name`` (case-insensitive)."""
        found = self._index.get(name.lower())
        if not found:
            raise QueryError("unknown column: %s" % name)
        if len(found) > 1:
            raise QueryError("ambiguous column: %s" % name)
        return found[0]


def _read_table(directory, name):
    path = os.path.join(directory, name + ".csv")
    if not os.path.isfile(path):
        raise QueryError("unknown table: %s" % name)
    try:
        with open(path, newline="", encoding="utf-8-sig") as f:
            reader = csv.reader(f)
            header = next(reader, None)
            if header is None:
                raise QueryError("table %s has no header line" % name)
            width = len(header)
            rows = []
            for record in reader:
                if not record:
                    continue
                if len(record) > width:
                    raise QueryError(
                        "table %s, line %d: %d fields but the header has %d"
                        % (name, reader.line_num, len(record), width)
                    )
                values = [_convert(v) for v in record]
                values.extend([None] * (width - len(values)))
                rows.append(tuple(values))
    except QueryError:
        raise
    except (OSError, UnicodeDecodeError, csv.Error) as e:
        raise QueryError("cannot read table %s: %s" % (name, e))
    return _Table(header, rows)


# ---------------------------------------------------------------------------
# Values

_AGGREGATES = {"COUNT", "SUM", "AVG", "MIN", "MAX"}
_SCALARS = {
    # name: (min args, max args or None)
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}


def _is_number(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def _kind(v):
    if isinstance(v, bool):
        return "boolean"
    if _is_number(v):
        return "number"
    if isinstance(v, str):
        return "string"
    return type(v).__name__


def _describe(v):
    if v is True:
        return "TRUE"
    if v is False:
        return "FALSE"
    if isinstance(v, str):
        return "'%s'" % v.replace("'", "''")
    return repr(v)


def _compare(a, b):
    """Compare two non-NULL values: -1, 0 or 1. Raises on mixed types."""
    ka, kb = _kind(a), _kind(b)
    if ka != kb:
        raise QueryError(
            "cannot compare %s %s with %s %s" % (ka, _describe(a), kb, _describe(b))
        )
    if a < b:
        return -1
    if a > b:
        return 1
    return 0


def _key(v):
    """A hashable key that equates values that compare equal (1 and 1.0)
    but keeps booleans distinct from numbers."""
    if v is None:
        return (0,)
    if isinstance(v, bool):
        return (1, v)
    if _is_number(v):
        return (2, v)
    return (3, v)


def _text(v):
    if v is True:
        return "true"
    if v is False:
        return "false"
    return str(v)


def _check_bool(v, what):
    if v is not None and not isinstance(v, bool):
        raise QueryError("%s needs a boolean, got %s" % (what, _describe(v)))
    return v


def _and(a, b):
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def _or(a, b):
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def _not(a):
    return None if a is None else not a


_like_cache = {}


def _like_regex(pattern):
    rx = _like_cache.get(pattern)
    if rx is None:
        parts = []
        for ch in pattern:
            if ch == "%":
                parts.append(".*")
            elif ch == "_":
                parts.append(".")
            else:
                parts.append(re.escape(ch))
        rx = re.compile("".join(parts), re.DOTALL)
        _like_cache[pattern] = rx
    return rx


def _round(x, n=None):
    if not _is_number(x):
        raise QueryError("ROUND needs a number, got %s" % _describe(x))
    if n is not None and (not isinstance(n, int) or isinstance(n, bool)):
        raise QueryError("ROUND needs an integer number of places, got %s" % _describe(n))
    d = decimal.Decimal(repr(x)) if isinstance(x, float) else decimal.Decimal(x)
    if not d.is_finite():
        if n is None:
            raise QueryError("cannot round %s to an integer" % _describe(x))
        return x
    exp = decimal.Decimal(1).scaleb(-(n or 0))
    ctx = decimal.Context(prec=10000, rounding=decimal.ROUND_HALF_UP)
    try:
        q = d.quantize(exp, context=ctx)
    except decimal.InvalidOperation:
        q = d
    if n is None:
        return int(q)
    return float(q)


def _arith(op, a, b):
    if a is None or b is None:
        return None
    if not _is_number(a) or not _is_number(b):
        raise QueryError(
            "cannot apply %s to %s and %s" % (op, _describe(a), _describe(b))
        )
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    # "/"
    if b == 0:
        return None
    try:
        return a / b
    except OverflowError:
        raise QueryError("numeric overflow in %s / %s" % (_describe(a), _describe(b)))


_COMPARISONS = {
    "=": lambda c: c == 0,
    "!=": lambda c: c != 0,
    "<>": lambda c: c != 0,
    "<": lambda c: c < 0,
    "<=": lambda c: c <= 0,
    ">": lambda c: c > 0,
    ">=": lambda c: c >= 0,
}


def _children(expr):
    if isinstance(expr, nodes.Unary):
        return [expr.operand]
    if isinstance(expr, nodes.Binary):
        return [expr.left, expr.right]
    if isinstance(expr, nodes.IsNull):
        return [expr.expr]
    if isinstance(expr, nodes.InList):
        return [expr.expr] + list(expr.items)
    if isinstance(expr, nodes.Between):
        return [expr.expr, expr.low, expr.high]
    if isinstance(expr, nodes.Like):
        return [expr.expr, expr.pattern]
    if isinstance(expr, nodes.FuncCall):
        return list(expr.args)
    return []


def _is_aggregate(expr):
    return isinstance(expr, nodes.FuncCall) and expr.name.upper() in _AGGREGATES


def _has_aggregate(expr):
    if expr is None:
        return False
    if _is_aggregate(expr):
        return True
    return any(_has_aggregate(c) for c in _children(expr))


# ---------------------------------------------------------------------------
# Evaluation


class _Evaluator:
    def __init__(self, table):
        self.table = table

    # -- static checks ---------------------------------------------------

    def check(self, expr, where, allow_agg, in_agg=False):
        """Check columns, functions, arity and aggregate placement."""
        if isinstance(expr, nodes.Literal):
            return
        if isinstance(expr, nodes.Column):
            self.table.resolve(expr.name)
            return
        if isinstance(expr, nodes.FuncCall):
            name = expr.name.upper()
            if name in _AGGREGATES:
                if not allow_agg:
                    raise QueryError("aggregate %s is not allowed in %s" % (name, where))
                if in_agg:
                    raise QueryError("aggregates can't be nested: %s" % expr.text)
                if expr.star:
                    if name != "COUNT" or expr.args:
                        raise QueryError("only COUNT accepts *")
                elif len(expr.args) != 1:
                    raise QueryError(
                        "%s takes exactly 1 argument, got %d" % (name, len(expr.args))
                    )
                for a in expr.args:
                    self.check(a, where, allow_agg, True)
                return
            if name not in _SCALARS:
                raise QueryError("unknown function: %s" % expr.name)
            if expr.star:
                raise QueryError("%s does not accept *" % name)
            lo, hi = _SCALARS[name]
            n = len(expr.args)
            if n < lo or (hi is not None and n > hi):
                if lo == hi:
                    want = "%d argument%s" % (lo, "" if lo == 1 else "s")
                elif hi is None:
                    want = "at least %d argument%s" % (lo, "" if lo == 1 else "s")
                else:
                    want = "%d to %d arguments" % (lo, hi)
                raise QueryError("%s takes %s, got %d" % (name, want, n))
            for a in expr.args:
                self.check(a, where, allow_agg, in_agg)
            return
        if isinstance(
            expr,
            (nodes.Unary, nodes.Binary, nodes.IsNull, nodes.InList, nodes.Between, nodes.Like),
        ):
            for c in _children(expr):
                self.check(c, where, allow_agg, in_agg)
            return
        raise QueryError("unsupported expression: %r" % (expr,))

    @staticmethod
    def check_grouped(expr, group_by):
        """Every column outside an aggregate must lie within a GROUP BY
        expression."""
        if any(expr == g for g in group_by):
            return
        if _is_aggregate(expr):
            return
        if isinstance(expr, nodes.Column):
            raise QueryError(
                "column %s must appear in GROUP BY or be used in an aggregate"
                % (expr.text or expr.name)
            )
        for c in _children(expr):
            _Evaluator.check_grouped(c, group_by)

    # -- evaluation ------------------------------------------------------

    def eval(self, expr, row, group=None):
        """Evaluate ``expr`` on ``row``; ``group`` is the list of rows for
        aggregates (None when the query is not grouped)."""
        ev = self.eval
        if isinstance(expr, nodes.Literal):
            return expr.value
        if isinstance(expr, nodes.Column):
            return row[self.table.resolve(expr.name)]
        if isinstance(expr, nodes.Binary):
            op = expr.op.upper()
            a = ev(expr.left, row, group)
            b = ev(expr.right, row, group)
            if op == "AND":
                return _and(_check_bool(a, "AND"), _check_bool(b, "AND"))
            if op == "OR":
                return _or(_check_bool(a, "OR"), _check_bool(b, "OR"))
            if op in _COMPARISONS:
                if a is None or b is None:
                    return None
                return _COMPARISONS[op](_compare(a, b))
            if op == "||":
                if a is None or b is None:
                    return None
                return _text(a) + _text(b)
            if op in ("+", "-", "*", "/"):
                return _arith(op, a, b)
            raise QueryError("unknown operator: %s" % expr.op)
        if isinstance(expr, nodes.Unary):
            op = expr.op.upper()
            v = ev(expr.operand, row, group)
            if op == "NOT":
                return _not(_check_bool(v, "NOT"))
            if op == "-":
                if v is None:
                    return None
                if not _is_number(v):
                    raise QueryError("cannot negate %s" % _describe(v))
                return -v
            raise QueryError("unknown operator: %s" % expr.op)
        if isinstance(expr, nodes.IsNull):
            v = ev(expr.expr, row, group)
            return (v is not None) if expr.negated else (v is None)
        if isinstance(expr, nodes.InList):
            x = ev(expr.expr, row, group)
            items = [ev(i, row, group) for i in expr.items]
            if x is None:
                result = None
            else:
                result = False
                for item in items:
                    if item is None:
                        result = None
                    elif _compare(x, item) == 0:
                        result = True
                        break
            return _not(result) if expr.negated else result
        if isinstance(expr, nodes.Between):
            x = ev(expr.expr, row, group)
            lo = ev(expr.low, row, group)
            hi = ev(expr.high, row, group)
            ge = None if x is None or lo is None else _compare(lo, x) <= 0
            le = None if x is None or hi is None else _compare(x, hi) <= 0
            result = _and(ge, le)
            return _not(result) if expr.negated else result
        if isinstance(expr, nodes.Like):
            s = ev(expr.expr, row, group)
            p = ev(expr.pattern, row, group)
            for v in (s, p):
                if v is not None and not isinstance(v, str):
                    raise QueryError("LIKE needs strings, got %s" % _describe(v))
            if s is None or p is None:
                return None
            result = _like_regex(p).fullmatch(s) is not None
            return not result if expr.negated else result
        if isinstance(expr, nodes.FuncCall):
            name = expr.name.upper()
            if name in _AGGREGATES:
                return self.aggregate(name, expr, group)
            return self.scalar(name, expr, row, group)
        raise QueryError("unsupported expression: %r" % (expr,))

    def scalar(self, name, expr, row, group):
        if name == "COALESCE":
            for a in expr.args:
                v = self.eval(a, row, group)
                if v is not None:
                    return v
            return None
        args = [self.eval(a, row, group) for a in expr.args]
        if any(a is None for a in args):
            return None
        x = args[0]
        if name in ("LOWER", "UPPER", "LENGTH"):
            if not isinstance(x, str):
                raise QueryError("%s needs a string, got %s" % (name, _describe(x)))
            if name == "LOWER":
                return x.lower()
            if name == "UPPER":
                return x.upper()
            return len(x)
        if name == "ABS":
            if not _is_number(x):
                raise QueryError("ABS needs a number, got %s" % _describe(x))
            return abs(x)
        if name == "ROUND":
            return _round(*args)
        raise QueryError("unknown function: %s" % expr.name)

    def aggregate(self, name, expr, group):
        if group is None:  # pragma: no cover - prevented by grouping logic
            raise QueryError("aggregate %s used outside a grouped query" % name)
        if expr.star:
            return len(group)
        arg = expr.args[0]
        values = [v for v in (self.eval(arg, r) for r in group) if v is not None]
        if name == "COUNT":
            return len(values)
        if not values:
            return None
        if name in ("SUM", "AVG"):
            total = 0
            for v in values:
                if not _is_number(v):
                    raise QueryError("%s needs numbers, got %s" % (name, _describe(v)))
                total += v
            if name == "AVG":
                return total / len(values)
            return total
        best = values[0]
        for v in values[1:]:
            c = _compare(v, best)
            if (name == "MIN" and c < 0) or (name == "MAX" and c > 0):
                best = v
        return best

    def condition(self, expr, row, group, clause):
        v = self.eval(expr, row, group)
        if v is not None and not isinstance(v, bool):
            raise QueryError("%s condition must be boolean, got %s" % (clause, _describe(v)))
        return v is True


# ---------------------------------------------------------------------------
# Sorting


def _sort_cmp(desc_flags):
    def cmp(a, b):
        for x, y, desc in zip(a[1], b[1], desc_flags):
            if x is None and y is None:
                continue
            if x is None:
                return 1 if desc else -1
            if y is None:
                return -1 if desc else 1
            c = _compare(x, y)
            if c:
                return -c if desc else c
        return 0

    return cmp


# ---------------------------------------------------------------------------
# Entry point


def execute(select, directory):
    """Run the query ``select`` (a ``nodes.Select``) against the CSV files in
    ``directory`` and return a ``Result``."""
    table = _read_table(directory, select.table)
    ev = _Evaluator(table)
    group_by = list(select.group_by or [])

    # Output columns.
    if select.columns is None:
        items = [nodes.SelectItem(nodes.Column(h, h)) for h in table.header]
        names = list(table.header)
    else:
        items = list(select.columns)
        names = []
        for item in items:
            if item.alias is not None:
                names.append(item.alias)
            elif isinstance(item.expr, nodes.Column):
                names.append(table.header[table.resolve(item.expr.name)])
            else:
                names.append(item.expr.text)

    # Resolve ORDER BY items: ("out", index) or ("expr", expr).
    order = []
    lowered = [n.lower() for n in names]
    for oi in select.order_by or []:
        e = oi.expr
        if isinstance(e, nodes.Column) and e.name.lower() in lowered:
            order.append(("out", lowered.index(e.name.lower())))
        elif (
            isinstance(e, nodes.Literal)
            and isinstance(e.value, int)
            and not isinstance(e.value, bool)
        ):
            if not 1 <= e.value <= len(names):
                raise QueryError(
                    "ORDER BY position %d is out of range (1 to %d)" % (e.value, len(names))
                )
            order.append(("out", e.value - 1))
        else:
            order.append(("expr", e))

    # Static checks.
    if select.where is not None:
        ev.check(select.where, "WHERE", allow_agg=False)
    for g in group_by:
        ev.check(g, "GROUP BY", allow_agg=False)
    for item in items:
        ev.check(item.expr, "the column list", allow_agg=True)
    if select.having is not None:
        ev.check(select.having, "HAVING", allow_agg=True)
    for kind, e in order:
        if kind == "expr":
            ev.check(e, "ORDER BY", allow_agg=True)

    grouped = (
        bool(group_by)
        or any(_has_aggregate(i.expr) for i in items)
        or _has_aggregate(select.having)
        or any(kind == "expr" and _has_aggregate(e) for kind, e in order)
    )
    if grouped:
        for item in items:
            ev.check_grouped(item.expr, group_by)
        if select.having is not None:
            ev.check_grouped(select.having, group_by)
        for kind, e in order:
            if kind == "expr":
                ev.check_grouped(e, group_by)

    for value, what in ((select.limit, "LIMIT"), (select.offset, "OFFSET")):
        if value is not None and (
            not isinstance(value, int) or isinstance(value, bool) or value < 0
        ):
            raise QueryError("%s must be a non-negative integer" % what)

    # Filter.
    rows = table.rows
    if select.where is not None:
        rows = [r for r in rows if ev.condition(select.where, r, None, "WHERE")]

    # Build (row, group) evaluation contexts.
    if grouped:
        if group_by:
            groups = {}
            for r in rows:
                k = tuple(_key(ev.eval(g, r)) for g in group_by)
                groups.setdefault(k, []).append(r)
            contexts = [(g[0], g) for g in groups.values()]
        else:
            contexts = [(rows[0] if rows else None, rows)]
    else:
        contexts = [(r, None) for r in rows]

    if select.having is not None:
        contexts = [
            (r, g) for r, g in contexts if ev.condition(select.having, r, g, "HAVING")
        ]

    # Project, computing sort keys alongside.
    out = []
    for r, g in contexts:
        values = tuple(ev.eval(item.expr, r, g) for item in items)
        keys = tuple(
            values[x] if kind == "out" else ev.eval(x, r, g) for kind, x in order
        )
        out.append((values, keys))

    if order:
        out.sort(key=functools.cmp_to_key(_sort_cmp([oi.desc for oi in select.order_by])))

    result_rows = [values for values, _ in out]

    if select.distinct:
        seen = set()
        unique = []
        for values in result_rows:
            k = tuple(_key(v) for v in values)
            if k not in seen:
                seen.add(k)
                unique.append(values)
        result_rows = unique

    start = select.offset or 0
    end = None if select.limit is None else start + select.limit
    result_rows = result_rows[start:end]

    return Result(names, result_rows)

"""Core query behaviour: API shape, tables, typing, names, syntax, ordering."""
import unittest

import minisql

from tests.support import DATA_DIR, MiniSQLTestCase, typed


class SpecExampleTests(MiniSQLTestCase):
    def test_spec_example(self):
        result = minisql.run(
            "SELECT name, price FROM products WHERE price > 10 "
            "ORDER BY price DESC",
            DATA_DIR,
        )
        self.assertEqual(list(result.columns), ["name", "price"])
        self.assertEqual(typed(result.rows),
                         typed([("widget", 25), ("gadget", 12.5)]))

    def test_result_shape(self):
        result = self.run_sql("SELECT g, x FROM nums")
        self.assertIsInstance(result.columns, list)
        for c in result.columns:
            self.assertIsInstance(c, str)
        self.assertIsInstance(result.rows, list)
        for r in result.rows:
            self.assertIsInstance(r, tuple)

    def test_query_error_is_exception(self):
        self.assertTrue(issubclass(minisql.QueryError, Exception))


class TableTests(MiniSQLTestCase):
    def test_missing_table_is_error(self):
        self.assertQueryError("SELECT * FROM nope")

    def test_star_selects_all_columns_in_file_order(self):
        self.assertRows("SELECT * FROM nums",
                        [("b", 2, None), ("a", 1, 1.5), ("b", 4, None),
                         ("a", None, 2.5), ("c", None, None)],
                        columns=["g", "x", "y"])

    def test_star_uses_header_spelling(self):
        self.assertColumns("SELECT * FROM mixed",
                           ["Name", "unit price", "from", "order", 'a"b',
                            "_id", "col2"])

    def test_empty_table(self):
        self.assertRows("SELECT * FROM empty", [], columns=["id", "x"])

    def test_quoted_table_name(self):
        self.assertRows('SELECT k FROM "my table"', [(1,), (2,)])

    def test_no_order_keeps_file_order(self):
        self.assertRows("SELECT id FROM sales",
                        [(1,), (2,), (3,), (4,), (5,), (6,)])


class ValueTypingTests(MiniSQLTestCase):
    def value_for(self, ident):
        result = self.run_sql("SELECT v FROM typed WHERE id = %d" % ident)
        self.assertEqual(len(result.rows), 1)
        return result.rows[0][0]

    def check(self, ident, expected):
        self.assertEqual(typed(self.value_for(ident)), typed(expected),
                         "typed.csv id %d" % ident)

    def test_negative_integer(self):
        self.check(1, -5)

    def test_plain_integer(self):
        self.check(19, 42)

    def test_integer_with_leading_zeros(self):
        self.check(8, 7)

    def test_negative_zero_integer(self):
        self.check(18, 0)

    def test_leading_dot_decimal(self):
        self.check(2, 0.5)

    def test_trailing_dot_decimal(self):
        self.check(3, 5.0)

    def test_negative_trailing_dot_decimal(self):
        self.check(20, -7.0)

    def test_negative_leading_dot_decimal(self):
        self.check(9, -0.5)

    def test_decimal(self):
        self.check(12, 3.25)

    def test_exponent_is_string(self):
        self.check(4, "1e3")

    def test_leading_space_is_string(self):
        self.check(5, " 5")

    def test_trailing_space_is_string(self):
        self.check(13, "5 ")

    def test_plus_sign_is_string(self):
        self.check(6, "+5")

    def test_lone_minus_is_string(self):
        self.check(7, "-")

    def test_lone_dot_is_string(self):
        self.check(14, ".")

    def test_two_dots_is_string(self):
        self.check(15, "1.2.3")

    def test_empty_is_null(self):
        self.check(10, None)

    def test_words_are_strings(self):
        self.check(11, "abc")
        self.check(16, "TRUE")
        self.check(17, "NULL")

    def test_header_row_not_data(self):
        self.assertEqual(len(self.run_sql("SELECT * FROM typed").rows), 20)


class ColumnNamingTests(MiniSQLTestCase):
    def test_plain_column(self):
        self.assertColumns("SELECT x FROM nums", ["x"])

    def test_plain_column_uses_header_spelling(self):
        self.assertColumns("SELECT name FROM mixed", ["Name"])
        self.assertColumns("SELECT NAME FROM mixed", ["Name"])
        self.assertColumns("SELECT X, G FROM nums", ["x", "g"])

    def test_column_match_case_insensitive(self):
        self.assertRows("SELECT nAmE, COL2, _ID FROM mixed",
                        [("Widget", 2, 1)])

    def test_as_alias(self):
        self.assertColumns("SELECT x AS total FROM nums", ["total"])

    def test_bare_alias(self):
        self.assertColumns("SELECT x total FROM nums", ["total"])

    def test_alias_spelling_preserved(self):
        self.assertColumns("SELECT x AS Total FROM nums", ["Total"])

    def test_quoted_alias(self):
        self.assertColumns('SELECT x AS "my total" FROM nums', ["my total"])
        self.assertColumns('SELECT x "my total" FROM nums', ["my total"])

    def test_quoted_alias_with_escaped_quote(self):
        self.assertColumns('SELECT x AS "a""b" FROM nums', ['a"b'])

    def test_alias_on_expression(self):
        self.assertRows("SELECT x * 2 AS dbl FROM nums WHERE g = 'b'",
                        [(4,), (8,)], columns=["dbl"])

    def test_expression_text_as_written(self):
        self.assertColumns("SELECT x * 2 FROM nums", ["x * 2"])
        self.assertColumns("SELECT x*2 FROM nums", ["x*2"])
        self.assertColumns("SELECT x  *  2 FROM nums", ["x  *  2"])
        self.assertColumns("SELECT X + 1 FROM nums", ["X + 1"])

    def test_count_star_name(self):
        self.assertColumns("SELECT COUNT(*) FROM nums", ["COUNT(*)"])
        self.assertColumns("SELECT count(*) FROM nums", ["count(*)"])
        self.assertColumns("SELECT COUNT( * ) FROM nums", ["COUNT( * )"])

    def test_function_and_literal_names(self):
        self.assertColumns("SELECT UPPER(g), 1, 'it''s', -x FROM nums",
                           ["UPPER(g)", "1", "'it''s'", "-x"])

    def test_multiple_columns(self):
        self.assertColumns("SELECT g, x AS n, x + 1 FROM nums",
                           ["g", "n", "x + 1"])

    def test_duplicate_columns_allowed(self):
        self.assertRows("SELECT x, x FROM nums WHERE g = 'b'",
                        [(2, 2), (4, 4)], columns=["x", "x"])


class NameTests(MiniSQLTestCase):
    def test_quoted_name_with_space(self):
        self.assertRows('SELECT "unit price" FROM mixed', [(3,)],
                        columns=["unit price"])

    def test_quoted_name_with_escaped_quote(self):
        self.assertRows('SELECT "a""b" FROM mixed', [("q",)], columns=['a"b'])

    def test_quoted_keyword_names(self):
        self.assertRows('SELECT "from", "order" FROM mixed', [("f", "o")],
                        columns=["from", "order"])

    def test_quoted_plain_name(self):
        self.assertRows('SELECT "Name" FROM mixed', [("Widget",)],
                        columns=["Name"])

    def test_underscore_and_digits(self):
        self.assertRows("SELECT _id, col2 FROM mixed", [(1, 2)])

    def test_keywords_not_usable_as_unquoted_names(self):
        self.assertQueryError("SELECT from FROM mixed")
        self.assertQueryError("SELECT order FROM mixed")
        self.assertQueryError("SELECT x AS select FROM nums")
        self.assertQueryError("SELECT x AS from FROM nums")
        self.assertQueryError("SELECT x AS where FROM nums")
        self.assertQueryError("SELECT x FROM nums ORDER BY order")

    def test_keywords_case_insensitive(self):
        self.assertRows(
            "select g, x as n from nums where x is not null and x > 1 "
            "order by x desc limit 1 offset 0",
            [("b", 4)], columns=["g", "n"])
        self.assertRows("SeLeCt DiStInCt g FrOm nums", [("b",), ("a",), ("c",)])
        self.assertRows(
            "select x from nums where x between 1 and 2 and g like 'b' "
            "and x not in (5)", [(2,)])
        self.assertRows(
            "select region, count(*) from sales group by region "
            "having count(*) > 1 order by region asc",
            [("north", 3), ("south", 2)])


class DistinctTests(MiniSQLTestCase):
    def test_distinct_single_column(self):
        self.assertRows("SELECT DISTINCT g FROM nums", [("b",), ("a",), ("c",)])

    def test_distinct_multiple_columns(self):
        self.assertRows("SELECT DISTINCT region, product FROM sales",
                        [("north", "apple"), ("south", "pear"),
                         ("north", "pear"), ("east", "apple"),
                         ("south", "apple")])

    def test_distinct_on_expression(self):
        self.assertRows("SELECT DISTINCT price * 2 FROM sales",
                        [(3.0,), (4,)])

    def test_distinct_with_order_by(self):
        self.assertRows("SELECT DISTINCT g FROM nums ORDER BY g",
                        [("a",), ("b",), ("c",)])

    def test_distinct_with_limit(self):
        self.assertRows("SELECT DISTINCT g FROM nums LIMIT 2",
                        [("b",), ("a",)])

    def test_distinct_star(self):
        self.assertRows("SELECT DISTINCT * FROM \"my table\"", [(1,), (2,)])


class OrderByTests(MiniSQLTestCase):
    def test_ascending_default_nulls_first(self):
        self.assertRows("SELECT x FROM nums ORDER BY x",
                        [(None,), (None,), (1,), (2,), (4,)])

    def test_explicit_asc(self):
        self.assertRows("SELECT x FROM nums ORDER BY x ASC",
                        [(None,), (None,), (1,), (2,), (4,)])

    def test_descending_nulls_last(self):
        self.assertRows("SELECT x FROM nums ORDER BY x DESC",
                        [(4,), (2,), (1,), (None,), (None,)])

    def test_mixed_int_float_sort(self):
        self.assertRows("SELECT price FROM sales ORDER BY price, id",
                        [(1.5,), (1.5,), (1.5,), (1.5,), (2,), (2,)])

    def test_strings_sort_by_code_point(self):
        self.assertRows("SELECT w FROM words WHERE w IS NOT NULL ORDER BY w",
                        [("Apple",), ("a",), ("a.c",), ("abc",), ("apple",),
                         ("banana",)])

    def test_stable_ascending(self):
        self.assertRows("SELECT g, x FROM nums ORDER BY g",
                        [("a", 1), ("a", None), ("b", 2), ("b", 4),
                         ("c", None)])

    def test_stable_descending(self):
        self.assertRows("SELECT g, x FROM nums ORDER BY g DESC",
                        [("c", None), ("b", 2), ("b", 4), ("a", 1),
                         ("a", None)])

    def test_stable_nulls(self):
        # Rows with NULL x keep file order (a before c) in both directions.
        self.assertRows("SELECT g FROM nums ORDER BY x",
                        [("a",), ("c",), ("a",), ("b",), ("b",)])
        self.assertRows("SELECT g FROM nums ORDER BY x DESC",
                        [("b",), ("b",), ("a",), ("a",), ("c",)])

    def test_multiple_keys(self):
        self.assertRows("SELECT g, x FROM nums ORDER BY g DESC, x DESC",
                        [("c", None), ("b", 4), ("b", 2), ("a", 1),
                         ("a", None)])
        self.assertRows("SELECT g, x FROM nums ORDER BY g, x DESC",
                        [("a", 1), ("a", None), ("b", 4), ("b", 2),
                         ("c", None)])

    def test_order_by_output_alias(self):
        self.assertRows("SELECT x * 10 AS t FROM nums ORDER BY t DESC",
                        [(40,), (20,), (10,), (None,), (None,)])

    def test_output_alias_shadows_input_column(self):
        # x refers to the output column (-x), not the input column x.
        self.assertRows("SELECT -x AS x FROM nums ORDER BY x",
                        [(None,), (None,), (-4,), (-2,), (-1,)])

    def test_order_by_position(self):
        self.assertRows("SELECT g, x FROM nums ORDER BY 2",
                        [("a", None), ("c", None), ("a", 1), ("b", 2),
                         ("b", 4)])
        self.assertRows("SELECT g, x FROM nums ORDER BY 1 DESC, 2",
                        [("c", None), ("b", 2), ("b", 4), ("a", None),
                         ("a", 1)])

    def test_order_by_position_of_expression(self):
        self.assertRows("SELECT id, -id FROM sales ORDER BY 2 LIMIT 2",
                        [(6, -6), (5, -5)])

    def test_order_by_expression_not_in_output(self):
        self.assertRows("SELECT g FROM nums ORDER BY x DESC",
                        [("b",), ("b",), ("a",), ("a",), ("c",)])
        self.assertRows("SELECT id FROM sales ORDER BY -id LIMIT 3",
                        [(6,), (5,), (4,)])

    def test_order_by_input_column_not_selected(self):
        self.assertRows("SELECT product FROM sales ORDER BY qty",
                        [("apple",), ("apple",), ("pear",), ("apple",),
                         ("apple",), ("pear",)])

    def test_order_by_non_bare_integer_expression_is_constant(self):
        # 1 + 0 is not a bare integer, so it is an expression (a constant);
        # the stable sort keeps file order.
        self.assertRows("SELECT x, g FROM nums ORDER BY 1 + 0",
                        [(2, "b"), (1, "a"), (4, "b"), (None, "a"),
                         (None, "c")])

    def test_order_by_unknown_column_is_error(self):
        self.assertQueryError("SELECT x FROM nums ORDER BY nope")


class LimitOffsetTests(MiniSQLTestCase):
    def test_limit(self):
        self.assertRows("SELECT id FROM sales LIMIT 2", [(1,), (2,)])

    def test_limit_zero(self):
        self.assertRows("SELECT id FROM sales LIMIT 0", [])

    def test_limit_larger_than_rows(self):
        self.assertRows("SELECT k FROM \"my table\" LIMIT 10", [(1,), (2,)])

    def test_limit_offset(self):
        self.assertRows("SELECT id FROM sales LIMIT 2 OFFSET 1", [(2,), (3,)])

    def test_offset_past_end(self):
        self.assertRows("SELECT id FROM sales LIMIT 2 OFFSET 10", [])

    def test_offset_zero(self):
        self.assertRows("SELECT id FROM sales LIMIT 1 OFFSET 0", [(1,)])

    def test_limit_after_sorting(self):
        self.assertRows("SELECT x FROM nums ORDER BY x DESC LIMIT 2",
                        [(4,), (2,)])
        self.assertRows(
            "SELECT id FROM sales ORDER BY price DESC, id LIMIT 2 OFFSET 1",
            [(3,), (1,)])

    def test_offset_without_limit_is_error(self):
        self.assertQueryError("SELECT id FROM sales OFFSET 1")

    def test_limit_requires_integer(self):
        self.assertQueryError("SELECT id FROM sales LIMIT")
        self.assertQueryError("SELECT id FROM sales LIMIT 1.5")
        self.assertQueryError("SELECT id FROM sales LIMIT 'a'")
        self.assertQueryError("SELECT id FROM sales LIMIT 1 OFFSET")


class SyntaxTests(MiniSQLTestCase):
    def test_trailing_semicolon(self):
        self.assertRows("SELECT k FROM \"my table\";", [(1,), (2,)])
        self.assertRows("SELECT k FROM \"my table\" LIMIT 1 ;", [(1,)])

    def test_whitespace_and_newlines(self):
        self.assertRows("  SELECT\n  k\nFROM\t\"my table\"\n  ", [(1,), (2,)])

    def test_syntax_errors(self):
        bad = [
            "",
            "SELECT",
            "SELEC x FROM nums",
            "SELECT FROM nums",
            "SELECT x",
            "SELECT 1",
            "SELECT x FROM",
            "SELECT x, FROM nums",
            "SELECT x FROM nums WHERE",
            "SELECT x FROM nums extra",
            "SELECT x FROM nums WHERE x = = 1",
            "SELECT (x FROM nums",
            "SELECT x) FROM nums",
            "SELECT 1 + FROM nums",
            "SELECT 'abc FROM nums",
            "SELECT \"abc FROM nums",
            "SELECT x FROM nums ORDER x",
            "SELECT x FROM nums GROUP x",
            "SELECT x FROM nums ORDER BY",
            "SELECT x FROM nums; SELECT x FROM nums",
            "SELECT x FROM nums WHERE x IN 1",
            "SELECT x FROM nums WHERE x IN ()",
            "SELECT x FROM nums WHERE x BETWEEN 1",
            "SELECT x FROM nums WHERE x IS 1",
            "SELECT x # 1 FROM nums",
            "SELECT *, x FROM nums",
            "SELECT x FROM nums LIMIT 1 WHERE x > 1",
            "SELECT x FROM nums ORDER BY x WHERE x > 1",
            "SELECT x AS FROM nums",
            "SELECT LOWER('a' FROM nums",
        ]
        for sql in bad:
            with self.subTest(sql=sql):
                self.assertQueryError(sql)


